input.command:
firecrawl interact --timeout 280 -c '
const out=[];
for (const z of ["10001","60601","33101","98101","96813"]) for (const p of [2,6]) {
  await page.goto(`https://postcalc.usps.com/Calculator/MailServices?country=0&ccode=US&oz=94107&omil=False&dz=${z}&dmil=False&retail=False&mdt=10%2F19%2F2026&mdz=13%3A59&m=6&hscode=False&p=${p}&o=0`,{waitUntil:"networkidle"});
  const t=await page.innerText("body");
  const g=(name)=>{const i=t.indexOf(name); if(i<0) return "NA"; const m=t.slice(i,i+400).match(/Normal Delivery Time\t([^\t]*)\t(\$[\d.]+)/); return m?m[2]+" ("+m[1]+")":"NA";};
  const hdr=t.match(/Package, weight[^\n]*\n[^\n]*/)[0].replace(/\n/g," | ");
  out.push(`${z} ${p}lb PM=${g("Priority Mail®\nSelect")} GA=${g("USPS Ground Advantage®\nSelect")} :: ${hdr}`);
}
console.log(out.join("\n"));
' 2>&1 | tail -12

